{"mt_tconst": "two-days-one-night", "mt_cr": ["IndieWire", "Eric Kohn"], "mt_cr_review_score": 91, "mt_cr_review_date": "May 25, 2014", "mt_cr_review": "Much of the movie relies on Cotillard's jittery expressions as she veers from tentatively hopeful to despondent and back again, sometimes within a matter of minutes, reflecting the ever-changing stability of job security among the lower class.", "mt_cr_review_full_url": "http://www.indiewire.com/article/cannes-review-two-days-one-night-starring-marion-cotillard-shows-the-dardenne-brothers-best-qualities?utm_source=feedburner&utm_medium=feed", "url": "https://www.metacritic.com/movie/two-days-one-night/critic-reviews", "spider": "mt_cr_review", "date": "20/08/2021"}
{"mt_tconst": "two-days-one-night", "mt_cr": ["Arizona Republic", "Bill Goodykoontz"], "mt_cr_review_score": 90, "mt_cr_review_date": "Jan 29, 2015", "mt_cr_review": "There is strength in simplicity, something the Dardenne brothers' Two Days, One Night and its brilliant star, Marion Cotillard, prove emphatically.", "mt_cr_review_full_url": "http://www.azcentral.com/story/entertainment/movies/2015/01/28/review-two-days-one-night-stars/22434959/", "url": "https://www.metacritic.com/movie/two-days-one-night/critic-reviews", "spider": "mt_cr_review", "date": "20/08/2021"}
