{"mt_tconst": "lincoln", "mt_cr": ["Time", "Richard Corliss"], "mt_cr_review_score": 80, "mt_cr_review_date": "Nov  8, 2012", "mt_cr_review": "This high-IQ sermon is long but never lazy. Renouncing his tendency to make every movie take emotional flight, Spielberg sticks to the story as Kushner has artfully compressed it. Lincoln is brain food and, at another pivotal moment in American political history, an instructive feast.", "mt_cr_review_full_url": "http://entertainment.time.com/2012/11/08/lincoln-spielbergs-urgent-civics-lesson/?iid=ent-main-lead", "url": "https://www.metacritic.com/movie/lincoln/critic-reviews", "spider": "mt_cr_review", "date": "20/08/2021"}
